import{_ as r,o as e,c as t,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"通用设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/general.md","filePath":"zh-CN/user-guide/settings/general.md","lastUpdated":1787586465000}'),a={name:"zh-CN/user-guide/settings/general.md"};function n(s,o,l,d,g,c){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="通用设置" tabindex="-1">通用设置 <a class="header-anchor" href="#通用设置" aria-label="Permalink to &quot;通用设置&quot;">​</a></h1><p>通用设置涵盖系统的核心运行行为、搜索窗口外观与布局参数、各结果类型的优先级权重以及预览组件的调度顺序。页面顶部共分为六个标签页：<strong>系统</strong>、<strong>快速搜索窗口</strong>、<strong>完整搜索窗口</strong>、<strong>预览窗口</strong>、<strong>快速导航</strong>与<strong>预览与缩略图</strong>。</p><h2 id="_1-系统-system" tabindex="-1">1. 系统（System） <a class="header-anchor" href="#_1-系统-system" aria-label="Permalink to &quot;1. 系统（System）&quot;">​</a></h2><ul><li><strong>开机自动启动 Lertaro</strong>：勾选后在 Windows 用户登录时自动启动 Lertaro。</li><li><strong>启动时自动检查更新</strong>：勾选后在软件每次启动时自动联网查询最新版本。</li><li><strong>自动静默更新</strong>：仅在开启“检查更新”时可用。检测到新版本后将在后台静默下载并自动无缝覆盖升级，免去手动操作。</li><li><strong>启用硬件加速</strong>：默认开启。若遇到笔记本独立显卡（如 NVIDIA Advanced Optimus）因 Lertaro 驻留而无法自动休眠切换核显的问题，可关闭该项改用软件渲染。修改后需重启 Lertaro 生效。</li><li><strong>隐藏托盘图标</strong>：勾选后隐藏 Windows 任务栏右下角的系统托盘图标。快速搜索窗口内的 Logo 图标依然能呼出完整的系统托盘菜单，不会丢失任何入口。</li><li><strong>启用 Everything 兼容服务 (IPC)</strong>：默认关闭。开启后，Lertaro 会在后台模拟标准 Everything Win32 IPC 协议接口，让 Directory Opus、Total Commander 等第三方软件无需额外安装运行 Everything 即可直接调用 Lertaro 的极速内存索引。</li><li><strong>启用模糊匹配</strong>：默认开启。开启时支持跳跃字符模糊匹配；关闭后要求普通查询词必须为连续子串（详见<a href="./../search-syntax.html"><strong>搜索语法</strong></a>）。即时生效无需重启。</li><li><strong>查询标记总前导字符</strong>：单字符文本框（默认为 <code>:</code>）。用于设置搜索框尾部后缀切分标记（如 <code>:.pdf</code>、<code>:@doc</code>、<code>:[S]</code>）的总引导符。</li><li><strong>日志等级</strong>：下拉选择“错误 / 警告 / 信息 (默认) / 调试”，控制系统各进程日志输出的详细程度。</li><li><strong>界面语言</strong>：下拉选择 Lertaro 的全局显示语言。</li></ul><h2 id="_2-快速搜索窗口-quick-search-window" tabindex="-1">2. 快速搜索窗口（Quick Search Window） <a class="header-anchor" href="#_2-快速搜索窗口-quick-search-window" aria-label="Permalink to &quot;2. 快速搜索窗口（Quick Search Window）&quot;">​</a></h2><p>本标签页用于精细化配置快速居中浮窗的几何尺寸与结果排序：</p><h3 id="搜索栏布局" tabindex="-1">搜索栏布局 <a class="header-anchor" href="#搜索栏布局" aria-label="Permalink to &quot;搜索栏布局&quot;">​</a></h3><ul><li><strong>搜索栏宽度 (像素)</strong>：取值范围 <code>300–1200px</code>，默认 <code>570px</code>。</li><li><strong>搜索栏高度 (像素)</strong>：取值范围 <code>45–120px</code>，默认 <code>60px</code>。该数值会按比例同步驱动结果列表的图标大小、行高与字体字号，确保视觉协调。</li><li><strong>搜索框内显示时钟</strong>：开启后，在搜索框为空时将提示文字替换为当前实时日期、星期与时间。输入文字后时钟自动隐藏。</li><li><strong>再次按下快捷键时打开完整窗口</strong>：开启后，在快速窗口已显示状态下再次按下全局呼出热键，将携带当前输入内容直接切换至完整主搜索窗口。</li><li><strong>锁定位置</strong>：开启后禁止鼠标拖拽移动快速窗口，防止误触改变位置。</li><li><strong>重置布局设置</strong>：一键将快速窗口尺寸与布局恢复为系统初始默认值。</li></ul><h3 id="结果类型优先级与触发符" tabindex="-1">结果类型优先级与触发符 <a class="header-anchor" href="#结果类型优先级与触发符" aria-label="Permalink to &quot;结果类型优先级与触发符&quot;">​</a></h3><ul><li><strong>优先级排序列表</strong>：支持拖拽左侧手柄或上下移动各结果类型（应用程序、系统设置、文件、插件扩展项等）。排在前面的类型在综合搜索结果中享有更高的排列权重。</li><li><strong>专属单字符触发符</strong>：可为特定结果类型配置专属单字符前缀（如将文件过滤器设为 <code>;</code>）。在搜索框开头输入该字符即可直接过滤出该类型的专属结果。</li></ul><h2 id="_3-完整搜索窗口-full-search-window" tabindex="-1">3. 完整搜索窗口（Full Search Window） <a class="header-anchor" href="#_3-完整搜索窗口-full-search-window" aria-label="Permalink to &quot;3. 完整搜索窗口（Full Search Window）&quot;">​</a></h2><p>用于配置大尺寸主搜索窗口（<code>Ctrl+F</code>）的默认行为与表格视图：</p><ul><li><strong>窗口宽度 / 高度 (像素)</strong>：宽度范围 <code>640–2000px</code>（默认 <code>854px</code>），高度范围 <code>400–1400px</code>（默认 <code>480px</code>）。</li><li><strong>仅允许一个完整搜索窗口</strong>：开启后，再次打开完整窗口将直接激活已有实例，避免重复创建多开。</li><li><strong>重置搜索窗口设置</strong>：一键恢复主窗口默认宽高设置。</li><li><strong>结果表格列顺序</strong>：拖拽自定义表格视图中各列（名称、路径、修改时间等）的先后排列顺序。</li><li><strong>侧边栏筛选顺序</strong>：拖拽调整主窗口左侧分类筛选栏的展示顺序；筛选栏会实时动态呈现当前关键词在各分类下的匹配条目数量。</li><li><strong>动作菜单分组顺序</strong>：拖拽调整上下文动作菜单（<code>Ctrl+O</code>）中各功能分组的显示先后。</li></ul><h2 id="_4-预览窗口-preview-window" tabindex="-1">4. 预览窗口（Preview Window） <a class="header-anchor" href="#_4-预览窗口-preview-window" aria-label="Permalink to &quot;4. 预览窗口（Preview Window）&quot;">​</a></h2><ul><li><strong>预览窗口宽度 / 高度 (像素)</strong>：宽度范围 <code>250–900px</code>，高度范围 <code>250–1200px</code>。</li><li><strong>重置预览窗口设置</strong>：将 QuickLook 预览浮窗的尺寸重置为标准默认比例。系统会自动计算避免预览窗口超出当前显示器的工作可视区域。</li></ul><h2 id="_5-快速导航-quick-navigation" tabindex="-1">5. 快速导航（Quick Navigation） <a class="header-anchor" href="#_5-快速导航-quick-navigation" aria-label="Permalink to &quot;5. 快速导航（Quick Navigation）&quot;">​</a></h2><ul><li><strong>提供者顺序</strong>：通过上下箭头或拖拽手柄，调整鼠标快速导航级联菜单根层级各个数据源提供者（收藏夹、历史记录、已打开文件夹、第三方管理器书签等）的分组排列顺序。</li></ul><h2 id="_6-预览与缩略图-previews-thumbnails" tabindex="-1">6. 预览与缩略图（Previews &amp; Thumbnails） <a class="header-anchor" href="#_6-预览与缩略图-previews-thumbnails" aria-label="Permalink to &quot;6. 预览与缩略图（Previews &amp; Thumbnails）&quot;">​</a></h2><ul><li><strong>文件预览提供者顺序</strong>：调整多个预览插件（如内置富文本/媒体解码器与第三方 QuickLook 桥接）的调用优先级。</li><li><strong>缩略图提供者顺序</strong>：调整结果列表中文件图标与缩略图提取组件的调用优先级。</li></ul>',19)])])}const p=r(a,[["render",n]]);export{u as __pageData,p as default};
